// [DIAG5] 2026-09-12 (GPU-local-payload round). TWO cross-binary bridge
// attempts to reach native/src/glyph_system.cpp's tiled "space" glyph bytes
// from this file both failed, for a reason neither round had actually
// checked: the real include/link inputs `native/build-gpu.ps1` feeds to this
// file are NOT the tools/rexglue-source headers/targets this investigation
// had been editing.
//
//   - Round 1 (`extern "C" Fable2Glyph_TryGetTiledSpaceGlyphBytesForA`,
//     fable2_053.log round) assumed both translation units linked into the
//     same executable -- wrong, since this file compiles into
//     rexgpu-xenos.dll, a separate DLL, while glyph_system.cpp compiles into
//     the host executable.
//   - Round 2 (`rex::Runtime::RegisterContentOverrideProvider`/
//     `TryGetContentOverride`, link-fix round) assumed that adding a public
//     method to tools/rexglue-source's `Runtime` class would reach this
//     file, since both the host exe and rexgpu-xenos.dll link `rexruntime`.
//     Compiling failed with "no member named 'TryGetContentOverride' in
//     'rex::Runtime'" -- **not** a linker error, a compile error, which
//     means this file was not even seeing our edited header.
//
// Inspecting the actual build inputs (`native/build-gpu.ps1`,
// `native/gpu/CMakeLists.txt`, and both `native/build.log` and
// `native/build-gpu.log`'s CMake configure output) resolved why:
// `native/gpu/CMakeLists.txt` -- a SEPARATE, standalone CMake project used
// to build just rexgpu-xenos.dll quickly -- does `find_package(rexglue
// CONFIG REQUIRED)` against the PREBUILT SDK package
// (tools/rexglue-sdk/win-amd64, located via `-DCMAKE_PREFIX_PATH`), then
// `add_library(rexruntime ALIAS rex::runtime)` to satisfy this target's
// `target_link_libraries(rexgpu-xenos PRIVATE rexruntime ...)` -- so
// "rexruntime" here IS the prebuilt import library, not anything built from
// tools/rexglue-source/src/system/*. It only pulls actual SOURCE from
// tools/rexglue-source for ONE thing: `add_subdirectory("${REXGLUE_ROOT}
// /src/graphics" graphics)` -- i.e. exactly (and only) the
// `REXGPU_XENOS_SOURCES` list in src/graphics/CMakeLists.txt, which is why
// edits to THIS file (cache.cpp) really do take effect (confirmed multiple
// times already, e.g. the fable2_053.log round's 11 logged texture
// creations), while edits to anything under tools/rexglue-source/src/system
// (runtime.cpp, xfile.cpp, host_path_file.cpp -- all instrumented in
// earlier rounds) or tools/rexglue-source/src/core never do: none of those
// directories are ever pulled in by any script this project actually runs.
// `native/build.log` (the MAIN `fable2.exe` build, `win-amd64-release`
// preset) confirms the SAME is true there: its configure step also logs
// "Found ReXGlue SDK 0.10.0 at .../tools/rexglue-sdk/win-amd64/lib/cmake
// /rexglue" (never "Using ReXGlue SDK from source tree", which is what
// `REXSDK_DIR` being actually set would produce) -- `REXSDK_DIR` is never
// set by build.ps1, build-gpu.ps1, or CMakePresets.json, so the host
// executable ALSO links the prebuilt rexruntime.dll, not anything rebuilt
// from tools/rexglue-source/src/system. (This retroactively explains, more
// simply than the "OpenMapped() mmap bypass" hypothesis recorded in the
// fable2_053.log round section of AI_HANDOFF.md, why the
// HostPathFile::ReadSync DIAG5 hook from two rounds ago never fired: that
// file was never compiled into anything this whole time, since
// src/filesystem is likewise never pulled in by any real build script.)
// `Runtime::instance()`/`memory()`, used a few lines below in
// DiagGetGuestPhysicalPointer(), still work fine despite all this: they are
// pre-existing methods already compiled into whatever rexruntime.dll
// snapshot is on disk, unlike anything added to tools/rexglue-source after
// that snapshot was built.
//
// Given that, the fix is GPU-local, not cross-binary at all: the tiled
// "space" glyph is a fixed, already-known 16384-byte byte array (computed
// once, offline, from the shipped pc/assets/glyphs/space_64.bin asset via
// the exact same GetTiledOffset2D()/TilePixels() algorithm
// native/src/glyph_system.cpp already uses for every other glyph -- verified
// bijective across all 4096 pixel blocks, i.e. every input byte lands at a
// distinct output offset with none left over or overlapping). It is
// embedded directly below as `kDiagTiledSpaceGlyphBytes`, so this file needs
// nothing from native/src/glyph_system.cpp, no cross-binary call, and no
// change to any prebuilt SDK header or library. Nothing in
// native/src/glyph_system.cpp was duplicated to produce it -- only its
// already-public output bytes were computed once, here, offline.

